<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import { router } from '@inertiajs/vue3';
const props = defineProps({ project: Object, clients: Array, sources: Array, statuses: Array, costCategories: Array });
const tab = ref('ringkasan');
const paymentForm = useForm({ tahapan_pembayaran: '', jumlah_bayar: '', tanggal_bayar: new Date().toISOString().slice(0, 10), metode_pembayaran: '' });
const costForm = useForm({ kategori_modal_id: '', nama_item: '', jumlah_biaya: '', tanggal_pengeluaran: new Date().toISOString().slice(0, 10), catatan: '', bukti_nota: null });
const invoiceForm = useForm({ nomor_invoice: '', tanggal_terbit: new Date().toISOString().slice(0, 10), tanggal_jatuh_tempo: '', nominal_tagihan: '', file_invoice: null, catatan: '' });
const money = value => new Intl.NumberFormat('id-ID', { style: 'currency', currency: props.project.mata_uang || 'IDR', maximumFractionDigits: 0 }).format(value);
function addPayment() { paymentForm.post(`/proyek/${props.project.id}/pembayaran`, { onSuccess: () => paymentForm.reset('tahapan_pembayaran', 'jumlah_bayar', 'metode_pembayaran') }); }
function addCost() { costForm.post(`/proyek/${props.project.id}/modal`, { onSuccess: () => costForm.reset('kategori_modal_id', 'nama_item', 'jumlah_biaya', 'catatan') }); }
function uploadInvoice() { invoiceForm.post(`/proyek/${props.project.id}/invoice/upload`, { onSuccess: () => invoiceForm.reset() }); }
const paidPercent = computed(() => props.project.nilai_bersih_kontrak ? Math.min(100, Number(props.project.total_dibayar) / Number(props.project.nilai_bersih_kontrak) * 100) : 0);
</script>
<template>
    <Head :title="project.judul_proyek" /><AuthenticatedLayout>
        <template #header><div class="flex w-full items-center justify-between"><div><p class="font-mono text-xs text-slate-500">{{ project.kode_proyek }}</p><h1 class="text-2xl font-semibold text-slate-900">{{ project.judul_proyek }}</h1></div><Link v-if="!project.apakah_terkunci" :href="`/proyek/${project.id}/edit`" class="rounded-lg border px-4 py-2 text-sm">Edit</Link><span v-else class="rounded-full bg-emerald-50 px-3 py-1 text-sm text-emerald-700">Terkunci · Selesai / Lunas</span></div></template>
        <main class="mx-auto max-w-7xl space-y-6 px-4 py-8 sm:px-6 lg:px-8">
            <section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="rounded-2xl border bg-white p-5"><p class="text-sm text-slate-500">Kontrak bersih</p><p class="mt-2 font-mono text-xl">{{ money(project.nilai_bersih_kontrak) }}</p></div><div class="rounded-2xl border bg-white p-5"><p class="text-sm text-slate-500">Total modal</p><p class="mt-2 font-mono text-xl">{{ money(project.total_modal) }}</p></div><div class="rounded-2xl border bg-white p-5"><p class="text-sm text-slate-500">Laba bersih</p><p class="mt-2 font-mono text-xl text-emerald-700">{{ money(project.laba_bersih) }}</p></div><div class="rounded-2xl border bg-white p-5"><p class="text-sm text-slate-500">Piutang</p><p class="mt-2 font-mono text-xl text-violet-700">{{ money(project.sisa_tagihan) }}</p></div></section>
            <section class="rounded-2xl border bg-white p-6"><div class="flex flex-wrap gap-2 border-b pb-4"><button v-for="name in ['ringkasan', 'pembayaran', 'modal', 'dokumen']" :key="name" @click="tab = name" class="rounded-lg px-3 py-2 text-sm capitalize" :class="tab === name ? 'bg-slate-900 text-white' : 'text-slate-600 hover:bg-slate-100'">{{ name }}</button></div>
                <div v-if="tab === 'ringkasan'" class="grid gap-6 py-6 lg:grid-cols-2"><div><h2 class="font-semibold">Informasi proyek</h2><dl class="mt-4 space-y-3 text-sm"><div class="flex justify-between"><dt class="text-slate-500">Klien</dt><dd>{{ project.klien.nama_klien }}</dd></div><div class="flex justify-between"><dt class="text-slate-500">Sumber order</dt><dd>{{ project.sumber_order.nama_sumber }}</dd></div><div class="flex justify-between"><dt class="text-slate-500">Status</dt><dd>{{ project.status.nama_status }}</dd></div><div class="flex justify-between"><dt class="text-slate-500">Mulai / deadline</dt><dd>{{ project.tanggal_mulai }} / {{ project.tanggal_deadline || '—' }}</dd></div><div class="flex justify-between"><dt class="text-slate-500">Margin</dt><dd>{{ project.margin_keuntungan }}%</dd></div><div class="flex justify-between"><dt class="text-slate-500">Tech stack</dt><dd>{{ project.tech_stack || '—' }}</dd></div><div v-if="project.url_produksi" class="flex justify-between"><dt class="text-slate-500">Produksi</dt><dd><a :href="project.url_produksi" target="_blank" rel="noopener" class="text-blue-700">Buka situs</a></dd></div><div v-if="project.url_repository" class="flex justify-between"><dt class="text-slate-500">Repository</dt><dd><a :href="project.url_repository" target="_blank" rel="noopener" class="text-blue-700">Buka repository</a></dd></div></dl></div><div><h2 class="font-semibold">Progress pembayaran</h2><div class="mt-5 h-2 rounded-full bg-slate-100"><div class="h-2 rounded-full bg-violet-500" :style="{ width: `${paidPercent}%` }"></div></div><p class="mt-2 text-sm text-slate-500">{{ money(project.total_dibayar) }} dari {{ money(project.nilai_bersih_kontrak) }}</p><p class="mt-5 whitespace-pre-line text-sm text-slate-600">{{ project.deskripsi || 'Deskripsi belum diisi.' }}</p></div></div>
                <div v-if="tab === 'pembayaran'" class="grid gap-8 py-6 lg:grid-cols-2"><form v-if="!project.apakah_terkunci" @submit.prevent="addPayment" class="space-y-4"><h2 class="font-semibold">Catat pembayaran</h2><input v-model="paymentForm.tahapan_pembayaran" placeholder="Tahapan, contoh DP 50%" required class="w-full rounded-lg border-slate-300"/><input v-model="paymentForm.jumlah_bayar" type="number" min="0.01" step="0.01" placeholder="Jumlah bayar" required class="w-full rounded-lg border-slate-300"/><input v-model="paymentForm.tanggal_bayar" type="date" required class="w-full rounded-lg border-slate-300"/><input v-model="paymentForm.metode_pembayaran" placeholder="Metode pembayaran" class="w-full rounded-lg border-slate-300"/><input type="file" accept=".pdf,.jpg,.jpeg,.png" @input="paymentForm.bukti_transfer = $event.target.files[0]" class="w-full text-sm"/><button class="rounded-lg bg-slate-900 px-4 py-2 text-sm text-white">Simpan pembayaran</button></form><p v-else class="text-sm text-slate-500">Proyek terkunci; tidak bisa menambah pembayaran.</p><div><h2 class="font-semibold">Riwayat pembayaran</h2><p v-for="item in project.pembayaran" :key="item.id" class="mt-3 flex justify-between border-b py-3 text-sm"><span>{{ item.tahapan_pembayaran }} · {{ item.tanggal_bayar }} <a v-if="item.bukti_transfer_path" :href="`/pembayaran/${item.id}/bukti`" class="text-blue-700">Bukti</a></span><strong>{{ money(item.jumlah_bayar) }}</strong></p></div></div>
                <div v-if="tab === 'modal'" class="grid gap-8 py-6 lg:grid-cols-2"><form v-if="!project.apakah_terkunci" @submit.prevent="addCost" class="space-y-4"><h2 class="font-semibold">Catat modal</h2><select v-model="costForm.kategori_modal_id" required class="w-full rounded-lg border-slate-300"><option value="">Pilih kategori</option><option v-for="category in costCategories" :key="category.id" :value="category.id">{{ category.nama_kategori }}</option></select><input v-model="costForm.nama_item" placeholder="Nama item" required class="w-full rounded-lg border-slate-300"/><input v-model="costForm.jumlah_biaya" type="number" min="0.01" step="0.01" placeholder="Biaya" required class="w-full rounded-lg border-slate-300"/><input v-model="costForm.tanggal_pengeluaran" type="date" required class="w-full rounded-lg border-slate-300"/><input type="file" accept=".pdf,.jpg,.jpeg,.png" @input="costForm.bukti_nota = $event.target.files[0]" class="w-full text-sm"/><button class="rounded-lg bg-slate-900 px-4 py-2 text-sm text-white">Simpan modal</button></form><p v-else class="text-sm text-slate-500">Proyek terkunci; tidak bisa menambah modal.</p><div><h2 class="font-semibold">Daftar modal</h2><p v-for="item in project.modals" :key="item.id" class="mt-3 flex justify-between border-b py-3 text-sm"><span>{{ item.nama_item }} · {{ item.kategori.nama_kategori }} <a v-if="item.bukti_nota_path" :href="`/modal/${item.id}/bukti`" class="text-blue-700">Bukti</a></span><strong>{{ money(item.jumlah_biaya) }}</strong></p></div></div>
                <div v-if="tab === 'dokumen'" class="space-y-6 py-6"><div class="grid gap-4 sm:grid-cols-2"><a :href="`/proyek/${project.id}/kontrak-pdf`" class="rounded-xl border p-5 hover:bg-slate-50"><strong>Surat kerja sama</strong><span class="mt-1 block text-sm text-slate-500">Buat atau unduh PDF kontrak</span></a><button v-if="project.sumber_order.nama_sumber === 'WhatsApp Direct' && !project.apakah_terkunci" @click="router.post(`/proyek/${project.id}/invoice/generate`)" class="rounded-xl border p-5 text-left hover:bg-slate-50"><strong>Generate invoice otomatis</strong><span class="mt-1 block text-sm text-slate-500">Invoice PDF dengan rekening freelancer</span></button></div><form v-if="project.sumber_order.nama_sumber !== 'WhatsApp Direct' && !project.apakah_terkunci" @submit.prevent="uploadInvoice" class="grid gap-3 rounded-xl border bg-slate-50 p-5 sm:grid-cols-2"><h3 class="font-semibold sm:col-span-2">Arsipkan invoice platform</h3><input v-model="invoiceForm.nomor_invoice" required placeholder="Nomor invoice platform" class="rounded-lg border-slate-300"/><input v-model="invoiceForm.nominal_tagihan" type="number" min="0.01" step="0.01" required placeholder="Nominal tagihan" class="rounded-lg border-slate-300"/><input v-model="invoiceForm.tanggal_terbit" type="date" required class="rounded-lg border-slate-300"/><input v-model="invoiceForm.tanggal_jatuh_tempo" type="date" class="rounded-lg border-slate-300"/><input type="file" accept=".pdf,.jpg,.jpeg,.png" required @input="invoiceForm.file_invoice = $event.target.files[0]" class="sm:col-span-2"/><button class="w-fit rounded-lg bg-slate-900 px-4 py-2 text-sm text-white">Upload invoice</button></form><div class="space-y-2"><h3 class="font-semibold">Invoice tersimpan</h3><div v-for="invoice in project.invoices" :key="invoice.id" class="flex items-center justify-between rounded-xl border p-4 text-sm"><span>{{ invoice.nomor_invoice }} · {{ money(invoice.nominal_tagihan) }} · {{ invoice.tipe_invoice }}</span><a :href="invoice.tipe_invoice === 'OTOMATIS' ? `/invoice/${invoice.id}/download` : `/invoice/${invoice.id}/file`" class="text-blue-700">Unduh</a></div></div></div>
            </section>
        </main>
    </AuthenticatedLayout>
</template>
